// CRIU - checkpoint/restore cycle
var CKPT = { tool: "CRIU", scope: "Linux process tree", file: "ckpt-JAH-LSC-000001.bin" };
var state = { counter: 41, openFiles: 3 };
console.log("Tool: " + CKPT.tool + " (" + CKPT.scope + ")");
var frozen = JSON.stringify(state);
console.log("Frozen -> " + CKPT.file + " (" + frozen.length + " bytes)");
state.counter = 999;
var restored = JSON.parse(frozen);
console.log("Restored counter=" + restored.counter + " openFiles=" + restored.openFiles + " -> RESTORE OK");
console.log("Restore cmd: criu restore -D ckpt/");

